60	/**
61	 * Relay a batch of messages from the veaOutbox
62	 * @param targetChainId The chain id of the veaOutbox chain
63	 * @param network The network to relay messages on
64	 * @param nonce The nonce of the message
65	 * @param maxBatchSize The maximum number of messages to relay in a single batch
66	 *
67	 * @returns The nonce of the last message relayed
68	 */
69	const relayBatch = async ({
70	  targetChainId: chainId,
71	  network,
72	  nonce,
73	  maxBatchSize,
74	  emitter,
75	  fetchBridgeConfig = getBridgeConfig,
76	  fetchCount = getCount,
77	  fetchVeaOutbox = getVeaOutbox,
78	  fetchProofAtCount = getProofAtCount,
79	  fetchMessageDataToRelay = getMessageDataToRelay,
80	  fetchBatcher = getBatcher,
81	}: RelayBatchDeps) => {
82	  try {
83	    const bridgeConfig = fetchBridgeConfig(chainId);
84	    const privateKey = process.env.PRIVATE_KEY;
85	    if (!privateKey) throw new MissingEnvironmentVariable("PRIVATE_KEY");
86	    const { batcherAddress, veaContracts, rpcOutbox } = bridgeConfig;
87	    const veaInboxAddress = veaContracts[network].veaInbox.address;
88	    const veaOutboxAddress = veaContracts[network].veaOutbox.address;
89	    const rpcOutboxUrls = Array.isArray(rpcOutbox) ? rpcOutbox : [rpcOutbox];
90	    const veaOutboxProvider = new FallbackRpcProvider(rpcOutboxUrls, emitter, chainId);
91	    const batcher = fetchBatcher(batcherAddress, privateKey, veaOutboxProvider);
92	    const veaOutbox = fetchVeaOutbox(veaOutboxAddress, privateKey, veaOutboxProvider, chainId, network);
93	    const count = await fetchCount(veaOutbox, chainId, network);
94	
95	    while (nonce < count) {
96	      let batchMessages = 0;
97	      let targets: string[] = [];
98	      let values: number[] = [];
99	      let datas: string[] = [];
100	
101	      while (batchMessages < maxBatchSize && nonce < count) {
102	        const isMsgRelayed = await veaOutbox.isMsgRelayed(nonce);
103	        if (isMsgRelayed) {
104	          nonce++;
105	          continue;
106	        }
107	        const [proof, messageData] = await Promise.all([
108	          fetchProofAtCount(chainId, nonce, count, veaInboxAddress, network),
109	          fetchMessageDataToRelay(chainId, veaInboxAddress, nonce, network),
110	        ]);
111	        const [to, from, data] = messageData;
112	        try {
113	          await veaOutbox.sendMessage.staticCall(proof, nonce, to, from, data);
114	          const callData = veaOutbox.interface.encodeFunctionData("sendMessage", [proof, nonce, to, from, data]);
115	          datas.push(callData);
116	          targets.push(veaOutboxAddress);
117	          values.push(0);
118	          batchMessages += 1;
119	          nonce++;
120	        } catch (err) {
121	          emitter.emit(BotEvents.MESSAGE_EXECUTION_FAILED, chainId, network, nonce, err);
122	          nonce++;
123	        }
124	      }
125	      if (batchMessages > 0) {
126	        const gasLimit = await batcher.batchSend.estimateGas(targets, values, datas);
127	        const tx = await batcher.batchSend(targets, values, datas, { gasLimit });
128	        const receipt = await tx.wait();
129	        emitter.emit(BotEvents.RELAY_BATCH, nonce, receipt?.hash);
130	      }
131	    }
132	    return nonce;
133	  } catch (error) {
134	    throw new ExecutionError("relayBatch", chainId, network, { cause: error });
135	  }
136	};
